/*
 * If the "what" pattern has bit set that blktrace version 1 does
 * not understand, then mask them out to avoid the warning.
 * The lower_32_bits() in record_blktrace_event() will do the
 * truncation anyway.
 */
if (bt->version == 1)
	what &= 0xffffffff;

if (WARN_ON_ONCE(bt->version == 1 &&
	     (what >> BLK_TC_SHIFT) > BLK_TC_END_V1))
	return;
